function bridgeMasterEMinCostAssignmentV35(cost){
  // Rectangular Hungarian assignment. Rows are plots; columns are existing tracks plus one
  // unassigned dummy per plot. This avoids order-dependent greedy steals at close crossings.
  const n=cost.length,m=n?cost[0].length:0;if(!n||m<n)return [];
  const u=new Float64Array(n+1),v=new Float64Array(m+1),p=new Int32Array(m+1),way=new Int32Array(m+1);
  for(let i=1;i<=n;i++){
    p[0]=i;let j0=0;const minv=new Float64Array(m+1);minv.fill(Infinity);const used=new Uint8Array(m+1);
    do{
      used[j0]=1;const i0=p[j0];let delta=Infinity,j1=0;
      for(let j=1;j<=m;j++)if(!used[j]){const cur=cost[i0-1][j-1]-u[i0]-v[j];if(cur<minv[j]){minv[j]=cur;way[j]=j0;}if(minv[j]<delta){delta=minv[j];j1=j;}}
      for(let j=0;j<=m;j++)if(used[j]){u[p[j]]+=delta;v[j]-=delta;}else minv[j]-=delta;
      j0=j1;
    }while(p[j0]!==0);
    do{const j1=way[j0];p[j0]=p[j1];j0=j1;}while(j0!==0);
  }
  const assignment=new Int32Array(n);assignment.fill(-1);for(let j=1;j<=m;j++)if(p[j]>0)assignment[p[j]-1]=j-1;return Array.from(assignment);
}
